"use strict";
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const icon = (name, extra = "") => `<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const date = value => value ? new Date(value).toLocaleString(undefined, {month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}) : "—";
const bytes = value => value >= 1048576 ? `${(value/1048576).toFixed(1)} MB` : value >= 1024 ? `${(value/1024).toFixed(1)} KB` : `${value} B`;
const timing = (value, missing = "Not recorded") => Number.isFinite(value) ? `${value.toFixed(3)} ms` : missing;
const operationLabel = value => ({registration:"Registration",verification:"Vault verification",candidate_verification:"External copy comparison",transfer_preparation:"Transfer preparation",package_receive:"Package reception"}[value] || value);
const cryptoTiming = (row, field) => timing(row[field], (field === "encryption_ms" && ["verification","candidate_verification"].includes(row.operation)) || (field === "decryption_ms" && ["registration","candidate_verification"].includes(row.operation)) ? "—" : "Not recorded");
function metricsNotice(){return state.data.processing_metrics_version>=2?"":`<div class="section-intro" role="status">${icon("alert")}<div><strong>Restart this node to enable encryption and decryption measurements.</strong> The site has been updated, but this running server is using the earlier version. Stop and start the server, refresh this page, then perform a new registration, verification, or transfer.</div></div>`;}
const evidenceLimit = () => state.data?.max_file_size || 32 * 1048576;
const packageLimit = () => state.data?.max_package_size || 80 * 1048576;
function filePicker({name="file",title="Select a file",help="",required=false,accept="",maximum=evidenceLimit(),kind="upload"}={}){
  return `<div class="file-picker" data-file-picker><label class="file-drop">${icon(kind)}<strong>${esc(title)}</strong><input name="${esc(name)}" type="file" ${required?"required":""} ${accept?`accept="${esc(accept)}"`:""} data-max-bytes="${maximum}"><p>${esc(help)}</p></label><div class="selected-file" hidden aria-live="polite"><span class="selection-state"></span><strong class="selection-name"></strong><p class="selection-size"></p><p class="selection-message">Selected on your computer. Submit this form to upload it.</p><p class="selection-error" role="alert"></p><button class="button secondary small-button" type="button" data-clear-file>${icon("close")} Remove selected file</button></div></div>`;
}
function fileSizeError(input){const file=input.files?.[0],maximum=Number(input.dataset.maxBytes);return file&&maximum&&file.size>maximum?`This file is too large (${bytes(file.size)}). Maximum allowed: ${bytes(maximum)}. Select a smaller file.`:"";}
function assertUploadSizes(form){for(const input of form.querySelectorAll('input[type="file"][data-max-bytes]')){const message=fileSizeError(input);if(message)throw new Error(message);}}
function bindFilePickers(root){root.querySelectorAll("[data-file-picker]").forEach(picker=>{
  const input=$("input[type=file]",picker),selection=$(".selected-file",picker);
  const update=()=>{const file=input.files?.[0],message=fileSizeError(input);input.setCustomValidity(message);selection.hidden=!file;selection.classList.toggle("invalid",Boolean(message));$(".selection-state",picker).textContent=message?"File exceeds the limit":"File selected";$(".selection-name",picker).textContent=file?.name||"";$(".selection-size",picker).textContent=file?`Size: ${bytes(file.size)}`:"";$(".selection-error",picker).textContent=message;$(".selection-message",picker).hidden=Boolean(message);};
  input.addEventListener("change",()=>{update();if(fileSizeError(input))input.reportValidity();});
  $("[data-clear-file]",picker).addEventListener("click",()=>{input.value="";input.setCustomValidity("");input.dispatchEvent(new Event("change",{bubbles:true}));input.focus();});update();
});}
function passwordChecks(value){return [["12–256 characters",value.length>=12&&value.length<=256],["An uppercase letter",/[A-Z]/.test(value)],["A lowercase letter",/[a-z]/.test(value)],["A number",/[0-9]/.test(value)],["A special character (spaces do not count)",/[^\p{L}\p{N}\s]/u.test(value)]];}
function configurePasswordPolicy(input,enabled){
  input.dataset.newPassword=enabled?"true":"false";input.maxLength=256;if(enabled)input.minLength=12;else input.removeAttribute("minlength");
  let list=input.parentElement.querySelector(".password-rules");if(!list&&enabled){list=document.createElement("ul");list.className="password-rules";list.setAttribute("aria-label","Password requirements");input.insertAdjacentElement("afterend",list);}
  const update=()=>{const active=input.dataset.newPassword==="true",rules=passwordChecks(input.value),missing=rules.filter(([,met])=>!met).map(([label])=>label);input.setCustomValidity(active&&input.value&&missing.length?`Password must contain: ${missing.join(", ")}.`:"");const rulesList=input.parentElement.querySelector(".password-rules");if(rulesList){rulesList.hidden=!active;rulesList.innerHTML=rules.map(([label,met])=>`<li class="${met?"met":""}">${icon(met?"check":"clock")}${esc(label)}</li>`).join("");}};
  if(!input.dataset.passwordBound){input.dataset.passwordBound="true";input.addEventListener("input",update);}update();
}
function bindNewPasswords(root){root.querySelectorAll('input[data-new-password="true"]').forEach(input=>configurePasswordPolicy(input,true));}
const badge = (value, label) => `<span class="badge ${esc(value)}">${icon(value === "alert" || value === "failed" ? "alert" : value === "verified" || value === "delivered" || value === "received" ? "check" : "clock")}${esc(label || ({verified:"Verified",alert:"Needs review",prepared:"Prepared",delivered:"Delivered",received:"Received",failed:"Unconfirmed"}[value] || value))}</span>`;
const state = {user:null, csrf:$("meta[name=csrf-token]").content, data:null, page:"overview", setup:false, query:"", filter:"all", archived:false, busy:false};
const pages = {
  overview:["Overview","A clear view of your evidence and its chain of custody.","YOUR INVESTIGATION WORKSPACE"],
  evidence:["Evidence vault","Registered originals, protected and ready for verification.","ACQUIRE & PROTECT"],
  custody:["Chain of custody","Follow the people and actions behind every evidence item.","A VERIFIABLE HISTORY"],
  transfers:["Secure transfers","Move evidence between trusted nodes with verified handoffs.","PROTECTED FROM END TO END"],
  analytics:["Processing analytics","Measured cryptographic performance and transfer efficiency.","SECURITY & EFFICIENCY"],
  audit:["Audit log","Signed records of evidence operations and workspace activity.","ACCOUNTABILITY, RECORDED"],
  settings:["Node settings","Your node identity, trusted peers, and authorized handlers.","WORKSPACE ADMINISTRATION"]
};
const writable = () => state.user && state.user.role !== "viewer";
let toastTimer;
function toast(message, error=false){ const el=$("#toast");el.textContent=message;el.classList.toggle("error",error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6500); }
async function api(path, options={}){
  const headers={"X-CSRF-Token":state.csrf,...options.headers};
  if(options.body && !(options.body instanceof FormData) && typeof options.body !== "string"){options.body=JSON.stringify(options.body);headers["Content-Type"]="application/json";}
  const response=await fetch(path,{...options,headers,credentials:"same-origin"});
  if(!response.ok){let body={};try{body=await response.json();}catch{} const error=new Error(body.error||"The operation could not be completed.");error.analysis=body.analysis;error.status=response.status;if(response.status===401 && state.user){state.user=null;closeModal();showAuth();}throw error;}
  if(options.blob) return response.blob();
  return response.json();
}
async function refresh({background=false}={}){
  const data=await api(background?"/api/updates":"/api/dashboard");
  const content=value=>JSON.stringify({...value,node:{...value.node,signature:undefined}});
  const changed=!state.data||content(state.data)!==content(data);state.data=data;
  $("#nav-count").textContent=data.stats.total;$("#alert-dot").hidden=true;
  const count=$("#alert-count");count.hidden=!data.stats.alerts;count.textContent=data.stats.alerts;
  const alertsButton=$('[data-action="alerts"]');alertsButton.title=data.stats.alerts+" open security alerts";alertsButton.setAttribute("aria-label",alertsButton.title);
  const editing=document.activeElement?.matches("#record-search,#status-filter");
  if(!background||(changed&&!editing&&!$("#modal").open))render();
  if(background&&changed&&$("#modal").open&&$("#modal-title").textContent==="Security alerts"&&!state.busy)alertsModal();
}
function showAuth(){ $("#loading").hidden=true;$("#workspace").hidden=true;$("#auth-view").hidden=false;$("#auth-title").textContent=state.setup?"Create your workspace":"Welcome back";$("#auth-description").textContent=state.setup?"Set up the first administrator for this node.":"Sign in to your investigation workspace.";$("#name-field").hidden=!state.setup;$("#name-field input").required=state.setup;$("#auth-button").textContent=state.setup?"Create workspace":"Sign in";$("#auth-help").textContent=state.setup?"Use 12–256 characters with uppercase and lowercase letters, a number, and a special character. Your administrator account can register evidence, trust nodes, and add handlers.":"Access is limited to authorized evidence handlers. All actions are recorded in the audit trail.";const password=$("#auth-form input[name=password]");password.autocomplete=state.setup?"new-password":"current-password";configurePasswordPolicy(password,state.setup); }
async function showWorkspace(){
  $("#auth-view").hidden=true;$("#loading").hidden=true;$("#workspace").hidden=false;
  $("#user-name").textContent=state.user.name;$("#user-role").textContent=state.user.role;
  const initials=state.user.name.split(/\s+/).map(p=>p[0]).slice(0,2).join("").toUpperCase();$("#user-avatar").textContent=initials;$("#top-avatar").textContent=initials;
  document.querySelectorAll(".heading-actions button").forEach(el=>el.hidden=!writable());
  await refresh();
}
function empty(title, description, action="", label="", kind="folder") {return `<div class="empty-state">${icon(kind)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="button secondary" data-action="${action}">${esc(label)}</button>`:""}</div>`;}
function fileType(manifest){return manifest.mime_type.startsWith("image/")?"image":manifest.mime_type.startsWith("audio/")?"audio":manifest.mime_type.startsWith("video/")?"video":"file";}
function fileCell(row){const m=row.manifest,t=fileType(m);return `<div class="file-cell"><span class="file-icon ${t}">${icon(t)}</span><button class="row-open" data-action="detail" data-id="${esc(row.id)}"><strong>${esc(m.filename)}</strong><small>${esc(row.id)}</small><small class="file-size">Size: ${bytes(m.size_bytes)}</small></button></div>`;}
function filteredEvidence(){const rows=state.archived&&state.page!=="overview"?(state.data.archived_evidence||[]):state.data.evidence;return rows.filter(row=>(state.filter==="all"||row.status===state.filter)&&JSON.stringify(row.manifest).toLowerCase().includes(state.query.toLowerCase()));}
function evidenceTable(rows, wide=false){if(!rows.length&&state.archived&&state.page!=="overview")return empty("No archived evidence","Archived records remain available here for inspection and restoration.","","","folder");if(!rows.length)return empty(state.query||state.filter!=="all"?"No matching evidence":"Your evidence starts here",state.query||state.filter!=="all"?"Try a different search or status filter.":"Register a file to create its SHA-256 fingerprint and signed custody record.",writable()&&!state.query?"register":"","Register evidence");return `<div class="table-wrap ${wide?"wide-table":""}"><table><thead><tr><th>Evidence file</th><th>Case reference</th>${wide?"<th>Acquisition source</th>":""}<th>Status</th><th>Registered</th><th aria-label="Actions"></th></tr></thead><tbody>${rows.map(row=>`<tr><td>${fileCell(row)}</td><td>${esc(row.manifest.case_id)}</td>${wide?`<td>${esc(row.manifest.source_kind.toUpperCase())}<br><span class="muted">${esc(row.manifest.source)}</span></td>`:""}<td>${row.archived?badge("archived","Archived")+" ":""}${badge(row.status)}</td><td>${date(row.registered_at)}</td><td><button class="icon-button" data-action="detail" data-id="${esc(row.id)}" aria-label="View ${esc(row.manifest.filename)}" title="View evidence">${icon("arrow")}</button></td></tr>`).join("")}</tbody></table></div>`;}
function searchToolbar(filter=true){return `<div class="toolbar"><label class="search-field" aria-label="Search records">${icon("search")}<input id="record-search" type="search" placeholder="Search ${state.page==="audit"?"audit records":"evidence"}…" value="${esc(state.query)}"></label>${filter?`<select id="status-filter" class="filter-select" aria-label="Filter by status"><option value="all">All statuses</option><option value="verified" ${state.filter==="verified"?"selected":""}>Verified</option><option value="alert" ${state.filter==="alert"?"selected":""}>Needs review</option></select>`:""}</div>`;}
const actions={registered:["Evidence registered","upload"],verified:["Integrity verified","shield"],verification_failed:["Verification needs review","alert"],transfer_prepared:["Transfer prepared","transfer"],transferred:["Evidence delivered","transfer"],received:["Evidence received","download"],accessed:["Evidence accessed","file"],downloaded:["Original downloaded","download"],report_generated:["Verification report created","file"],transfer_failed:["Delivery unconfirmed","alert"],alert_acknowledged:["Alert acknowledged","check"],peer_trusted:["Node identity trusted","shield"],login:["Handler signed in","user"],logout:["Handler signed out","logout"],user_created:["Handler account created","user"],transfer_rejected:["Transfer rejected","alert"],dashboard_accessed:["Workspace accessed","grid"],audit_exported:["Audit exported","download"],metrics_exported:["Metrics exported","chart"],login_failed:["Sign-in failed","alert"]};
function activityList(events,detail=false){
  return '<div class="activity-list">'+events.map(event=>{
    const p=event.payload,info=eventInfo(p);
    const record=[...state.data.evidence,...(state.data.archived_evidence||[])].find(row=>row.id===p.scope);
    const handler=record?.manifest.handler===p.actor?record.manifest.handler_name+" ("+p.actor+")":state.user?.username===p.actor?state.user.name+" ("+p.actor+")":p.actor;
    return '<div class="activity"><div class="activity-icon">'+icon(info.kind)+'</div><div><strong>'+esc(info.title)+'</strong><p class="activity-meta">Handler: '+esc(handler)+(p.scope!=="system"?' · '+esc(p.scope):"")+'</p>'+(info.explanation?'<p class="activity-explanation">'+esc(info.explanation)+'</p>':"")+(detail?'<p class="activity-meta">Custody step '+esc(p.sequence)+' · Node: '+esc(p.node_id)+'</p>':"")+'<time datetime="'+esc(p.timestamp)+'">'+date(p.timestamp)+'</time></div></div>';
  }).join("")+'</div>';
}
function overview(){
  const d=state.data,s=d.stats, recent=d.events.filter(e=>e.payload.scope!=="system" && e.payload.action!=="accessed").slice(0,5);
  const stats=[["Registered evidence",s.total,"folder","Originals encrypted at rest"],["Verified originals",s.verified,"shield","Hash & signature checks"],["Security alerts",s.alerts,"alert",s.alerts?"Open alerts need your review":"No open security alerts"],["Evidence transfers",s.transfers,"transfer","Inbound & outbound packages"]];
  return `<div class="security-banner"><span class="large-shield">${icon("shield")}</span><div><h2>${s.audit_valid?"Your evidence has a verifiable history":"Your audit trail needs review"}</h2><p>${s.audit_valid?"Signed custody records preserve each action. Encrypted originals stay protected in your vault.":"A custody record failed validation. Review the audit log before relying on evidence."}</p></div><span class="banner-tag">${s.audit_valid?"CUSTODY VALIDATED":"REVIEW REQUIRED"}</span></div>
  <div class="stats-grid">${stats.map(([title,value,kind,note])=>`<div class="stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(kind)}</span></div><div class="stat-value">${value.toString().padStart(2,"0")}</div><div class="stat-note ${kind==="shield"?"good":""}">${kind==="shield"?icon("check"):""}${note}</div></div>`).join("")}</div>
  <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Recent evidence <span class="count-pill">${s.total} total</span></h2><a class="text-link" href="#evidence">View vault ${icon("arrow")}</a></div>${searchToolbar()}<div id="evidence-table">${evidenceTable(filteredEvidence().slice(0,5))}</div><div class="panel-footer"><span>Showing up to 5 recently registered files</span><span>32 MB per file</span></div><div class="assurance-strip">${[["lock","Encrypted at rest","AES-256-GCM"],["shield","Signed acquisition","RSA-3072 signatures"],["chain","Traceable custody","Signed, linked events"]].map(([i,title,sub])=>`<div class="assurance-item">${icon(i)}<div><strong>${title}</strong><small>${sub}</small></div></div>`).join("")}</div></section>
  <section class="panel"><div class="panel-heading"><h2>Recent activity</h2><span class="count-pill">LIVE RECORDS</span></div>${recent.length?activityList(recent):empty("No evidence activity yet","Your acquisitions, checks, and handoffs will appear here.","","","clock")}<div class="quick-panel"><div class="eyebrow">PROVE IT STAYED THE SAME</div><p>Compare a file with its registered original. Even a one-byte change is detected.</p><a href="#evidence" class="text-link">Verify an evidence item ${icon("arrow")}</a></div></section></div>`;
}
function evidencePage(custody=false){
  const rows=state.archived?(state.data.archived_evidence||[]):state.data.evidence;
  return (custody?'<div class="section-intro">'+icon("chain")+'<div><strong>Every action is a signed link.</strong> Open an evidence item to inspect its acquisition, comparisons and verified handoffs.</div></div>':"")+
    '<section class="panel"><div class="panel-heading"><h2>'+(state.archived?"Archived evidence":custody?"Evidence custody records":"Registered evidence")+' <span class="count-pill">'+rows.length+' files</span></h2>'+icon("lock")+'</div><div class="vault-tabs"><button class="button secondary small-button '+(!state.archived?"selected":"")+'" data-action="active-vault">Active evidence ('+state.data.evidence.length+')</button><button class="button secondary small-button '+(state.archived?"selected":"")+'" data-action="archived-vault">Archived evidence ('+(state.data.archived_evidence||[]).length+')</button></div>'+
    searchToolbar()+'<div id="evidence-table">'+evidenceTable(filteredEvidence(),true)+'</div><div class="panel-footer"><span>Archive to remove from the active list; originals and custody history are retained.</span><span>'+rows.length+' records</span></div></section>';
}
function peersMarkup(){return state.data.peers.map(peer=>`<div class="peer-card"><span class="peer-icon">${icon("transfer")}</span><div><h3>${esc(peer.descriptor.name)}</h3><p>${esc(peer.node_id)}</p><p>${esc(peer.url||"Delivery URL not set; offline package exchange available")}</p><span class="mono fingerprint">${esc(peer.fingerprint)}</span>${state.user.role==="admin"?`<button class="text-link peer-edit" data-action="peer-url" data-id="${esc(peer.node_id)}">${peer.url?"Edit delivery URL":"Set delivery URL"}</button>`:""}</div></div>`).join("");}
function transfersPage(){const d=state.data;return `${metricsNotice()}<div class="section-intro">${icon("lock")}<div><strong>Only the receiving node can open a package.</strong> Sender signatures, original hashes, and custody records are checked before acceptance.</div></div><div class="cards-grid"><section class="panel"><div class="panel-heading"><h2>Trusted receiving nodes</h2>${state.user.role==="admin"?`<button class="text-link" data-action="peer">${icon("plus")} Trust a node</button>`:""}</div><div class="content-pad">${d.peers.length?peersMarkup():empty("Connect your second node","Exchange node identity files and confirm their fingerprints before trusting a peer.",state.user.role==="admin"?"peer":"","Trust a node","transfer")}</div></section><section class="panel"><div class="panel-heading"><h2>Package exchange</h2>${icon("shield")}</div><div class="content-pad"><p class="form-help">Send directly to a trusted node over HTTPS, or export an encrypted .scpkg file for offline delivery. A prepared package counts as delivered only after a signed network receipt.</p><div class="detail-actions">${writable()?`<button class="button primary" data-action="choose-transfer">${icon("transfer")} Send evidence</button><button class="button secondary" data-action="import">${icon("download")} Receive package</button>`:""}<a class="button secondary" href="/api/node/identity/download">${icon("download")} Node identity</a></div></div></section></div><section class="panel"><div class="panel-heading"><h2>Transfer history <span class="count-pill">${d.stats.transfers} total</span></h2></div>${d.transfers.length?`<div class="table-wrap"><table><thead><tr><th>Evidence ID</th><th>Direction</th><th>Status</th><th>Package size</th><th>Package encryption</th><th>Package decryption</th><th>Processing / delivery</th><th>Time</th></tr></thead><tbody>${d.transfers.map(t=>`<tr><td><button class="text-link" data-action="detail" data-id="${esc(t.evidence_id)}">${esc(t.evidence_id)}</button></td><td>${esc(t.direction)}</td><td>${badge(t.status)}</td><td>${bytes(t.bytes)}</td><td>${timing(t.encryption_ms,t.direction==="outbound"?"Not recorded":"—")}</td><td>${timing(t.decryption_ms,t.direction==="inbound"?"Not recorded":"—")}</td><td>${t.elapsed_ms.toFixed(2)} ms</td><td>${date(t.created_at)}</td></tr>`).join("")}</tbody></table></div>`:empty("No handoffs yet","Evidence transfer history will appear after you prepare or receive a package.","","","transfer")}</section>`;}
function analyticsPage(){
  const m=state.data.metrics;
  const avg=field=>{const values=m.map(row=>row[field]).filter(Number.isFinite);return values.length?(values.reduce((sum,value)=>sum+value,0)/values.length).toFixed(3):"—";};
  const rows=m.slice(0,15).reverse();
  const max=Math.max(1,...rows.map(row=>Math.max(row.hash_ms,row.signature_ms)));
  const line=field=>rows.map((row,i)=>`${20+i*(560/Math.max(rows.length-1,1))},${155-row[field]/max*130}`).join(" ");
  const summaries=[["encryption_ms","Average encryption time"],["decryption_ms","Average decryption time"],["hash_ms","Average hash time"],["signature_ms","Average signature time"],["total_ms","Average operation time"]];
  return `${metricsNotice()}<div class="cards-grid"><section class="panel"><div class="panel-heading"><h2>Cryptographic processing</h2><span class="count-pill">${m.length} recent operations</span></div>
    <div class="metric-summary crypto-summary">${summaries.map(([field,label])=>`<div><strong>${avg(field)}</strong><span>${label} · ms</span></div>`).join("")}</div>
    <div class="content-pad"><p class="settings-note">Averages include only recorded measurements. Encryption and decryption exclude file reads/writes, signing, and network delivery. Total time includes the other processing for that operation.</p></div>
    ${m.length?`<div class="chart-container"><svg class="performance-chart" viewBox="0 0 600 180" role="img" aria-label="Hash and signature times for the last 15 operations"><path d="M20 25H580M20 70H580M20 115H580M20 155H580" stroke="#edf2ed" fill="none"/><polyline points="${line("hash_ms")}" fill="none" stroke="#438369" stroke-width="2.5"/><polyline points="${line("signature_ms")}" fill="none" stroke="#b6c9a0" stroke-width="2.5"/>${rows.map((row,i)=>`<circle cx="${20+i*(560/Math.max(rows.length-1,1))}" cy="${155-row.hash_ms/max*130}" r="3" fill="#438369"/>`).join("")}</svg><div class="chart-labels"><span>Earlier operations</span><span>Latest operation</span></div><div class="chart-legend"><span><i></i>SHA-256</span><span><i class="signature-key"></i>RSA signature</span></div></div>`:empty("Measurements will appear here","Register, verify, or transfer evidence to measure cryptographic processing.","","","chart")}
    </section><section class="panel"><div class="panel-heading"><h2>Network traffic analysis</h2>${icon("chart")}</div><div class="content-pad"><p class="form-help">Capture a two-node transfer in Wireshark. The included tools summarize packet counts, protocol distribution, throughput, retransmissions, and observed TLS traffic.</p><div class="setting-row"><span>Packet capture</span><span>Wireshark / TShark</span></div><div class="setting-row"><span>Capture analysis</span><span>tools/analyze_traffic.py</span></div><div class="setting-row"><span>Encryption/decryption timing</span><span>Measured by each node</span></div><p class="settings-note">Packet captures measure network traffic. Cryptographic times are measured inside the application and appear in the processing metrics export.</p><a class="button secondary" href="/api/metrics/export">${icon("download")} Export processing metrics</a></div></section></div>
    <section class="panel"><div class="panel-heading"><h2>Recent processing measurements</h2></div><div class="content-pad"><p class="settings-note">Registration: vault encryption. Vault verification: vault decryption. Transfer preparation: package encryption and vault decryption. Package reception: vault encryption and package decryption. Vault operations use AES-256-GCM; package operations include AES-256-GCM and RSA-OAEP key wrapping/unwrapping. "Not recorded" identifies unavailable timings; — means the operation does not perform that step.</p></div>
    ${m.length?`<div class="table-wrap"><table><thead><tr><th>Evidence</th><th>Operation</th><th>Size</th><th>Hash time</th><th>Signature time</th><th>Encryption time</th><th>Decryption time</th><th>Total time</th></tr></thead><tbody>${m.slice(0,30).map(row=>`<tr><td>${esc(row.evidence_id)}</td><td>${esc(operationLabel(row.operation))}</td><td>${bytes(row.size_bytes)}</td><td>${timing(row.hash_ms)}</td><td>${timing(row.signature_ms)}</td><td>${cryptoTiming(row,"encryption_ms")}</td><td>${cryptoTiming(row,"decryption_ms")}</td><td>${timing(row.total_ms)}</td></tr>`).join("")}</tbody></table></div>`:empty("No measurements yet","Register or verify your first evidence item.","","","chart")}</section>`;
}
function auditRows(){const rows=state.data.events.filter(e=>JSON.stringify(e.payload).toLowerCase().includes(state.query.toLowerCase()));return rows.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Handler</th><th>Evidence / scope</th><th>Event hash</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${date(e.payload.timestamp)}</td><td>${esc(eventInfo(e.payload).title)}</td><td>${esc(e.payload.actor)}</td><td>${e.payload.scope!=="system"?`<button class="text-link" data-action="detail" data-id="${esc(e.payload.scope)}">${esc(e.payload.scope)}</button>`:"Workspace"}</td><td class="mono" title="${esc(e.event_hash)}">${esc(e.event_hash.slice(0,18))}…</td></tr>`).join("")}</tbody></table></div>`:empty("No matching events","Try a different search.","","","clock");}
function auditPage(){return `<div class="section-intro">${icon(state.data.stats.audit_valid?"shield":"alert")}<div><strong>${state.data.stats.audit_valid?"Local audit chains validated.":"Audit validation failed."}</strong> Events are signed and linked to previous records in each custody scope. Export includes the complete local audit trail.</div></div><section class="panel"><div class="panel-heading"><h2>Audit events</h2><a class="button secondary small-button" href="/api/audit/export">${icon("download")} Export signed audit</a></div>${searchToolbar(false)}<div id="audit-table">${auditRows()}</div><div class="panel-footer"><span>Showing the latest 100 local events</span><span>Append-only records</span></div></section>`;}
function settingsPage(){const d=state.data;return `<div class="cards-grid"><section class="panel"><div class="panel-heading"><h2>This node</h2>${icon("shield")}</div><div class="content-pad"><div class="setting-row"><span>Node name</span><span>${esc(d.node.name)}</span></div><div class="setting-row"><span>Node ID</span><span class="mono">${esc(d.node.node_id)}</span></div><div class="setting-row"><span>Storage</span><span>Encrypted local vault · SQLite</span></div><div class="setting-row"><span>Your access</span><span>${esc(state.user.role)}</span></div><p class="settings-note">Share the public node identity with your receiving system. Confirm its SHA-256 fingerprint through a separate, trusted channel before adding it as a peer.</p><a class="button secondary" href="/api/node/identity/download">${icon("download")} Download node identity</a></div></section><section class="panel"><div class="panel-heading"><h2>Trusted nodes</h2>${state.user.role==="admin"?`<button class="text-link" data-action="peer">${icon("plus")} Add node</button>`:""}</div><div class="content-pad">${d.peers.length?peersMarkup():empty("No trusted nodes","Add a peer identity to enable encrypted handoffs.",state.user.role==="admin"?"peer":"","Trust a node","transfer")}</div></section></div>${state.user.role==="admin"?`<section class="panel"><div class="panel-heading"><h2>Authorized handlers</h2><button class="text-link" data-action="user">${icon("plus")} Add handler</button></div><div id="users-table" class="content-pad"><p class="muted">Loading handler accounts…</p></div></section>`:""}`;}
function render(){if(!state.data)return;const [title,subtitle,eyebrow]=pages[state.page];$("#page-title").textContent=title;$("#breadcrumb").textContent=title;$("#page-subtitle").textContent=subtitle;$("#page-eyebrow").textContent=eyebrow;document.querySelectorAll("[data-nav]").forEach(a=>{const active=a.dataset.nav===state.page;a.classList.toggle("active",active);if(active)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current");});const views={overview,evidence:()=>evidencePage(),custody:()=>evidencePage(true),transfers:transfersPage,analytics:analyticsPage,audit:auditPage,settings:settingsPage};$("#page-content").innerHTML=views[state.page]();const search=$("#record-search");if(search)search.addEventListener("input",()=>{state.query=search.value;if(state.page==="audit")$("#audit-table").innerHTML=auditRows();else $("#evidence-table").innerHTML=evidenceTable(filteredEvidence().slice(0,state.page==="overview"?5:undefined),state.page!=="overview");});const filter=$("#status-filter");if(filter)filter.addEventListener("change",()=>{state.filter=filter.value;$("#evidence-table").innerHTML=evidenceTable(filteredEvidence().slice(0,state.page==="overview"?5:undefined),state.page!=="overview");});if(state.page==="settings"&&state.user.role==="admin")loadUsers();}
async function loadUsers(){try{const users=await api("/api/users");if(!$("#users-table"))return;$("#users-table").innerHTML=`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${date(u.created_at)}</td></tr>`).join("")}</tbody></table></div>`;}catch(error){toast(error.message,true);}}
function openModal(title,html,wide=false){$("#modal-title").textContent=title;$("#modal-content").innerHTML=html;bindFilePickers($("#modal-content"));bindNewPasswords($("#modal-content"));$("#modal").classList.toggle("wide-modal",wide);if(!$("#modal").open)$("#modal").showModal();}
function closeModal(){$("#modal").close();}
function formFooter(label){return `<p class="form-error" id="modal-error" role="alert"></p><div id="modal-analysis"></div><div class="form-actions"><button class="button secondary" type="button" data-action="close">Cancel</button><button class="button primary" type="submit">${esc(label)}</button></div>`;}
function submitForm(fn){
  $("#modal-form").addEventListener("submit",async event=>{
    event.preventDefault();const form=event.currentTarget,button=$("button[type=submit]",form);
    button.disabled=true;state.busy=true;$("#modal-error").textContent="";
    const panel=$("#modal-analysis");if(panel)panel.innerHTML="";
    try{assertUploadSizes(form);await fn(form);}
    catch(error){
      const errorEl=$("#modal-error");if(errorEl)errorEl.textContent=error.message;else toast(error.message,true);
      const analysisEl=$("#modal-analysis");
      if(analysisEl&&error.analysis)analysisEl.innerHTML=analysisMarkup(error.analysis)+'<button type="button" class="button secondary small-button" data-action="alerts">'+icon("alert")+' View security alerts</button>';
      if(state.user){try{await refresh({background:true});}catch{}}
    }finally{button.disabled=false;state.busy=false;}
  });
}
function registerModal(){openModal("Register evidence",`<p class="form-help">Create an encrypted original, signed registration manifest, and first custody record. Supports documents, images, audio, video, and USB-acquired files.</p><form id="modal-form">${filePicker({title:"Select the original evidence file",required:true,help:`Any file format · Maximum ${bytes(evidenceLimit())} · Stored without modification`})}<div class="form-grid"><label>Case reference<input name="case_id" required maxlength="200" placeholder="e.g. CASE-2026-001"></label><label>Acquisition type<select name="source_kind"><option value="manual">File acquisition</option><option value="usb">USB storage device</option><option value="network">Network acquisition</option><option value="mobile">Mobile device</option></select></label></div><label>Acquisition source<input name="source" required maxlength="200" placeholder="Device, location, or source reference"></label><div class="form-grid"><label>Acquired at<input type="datetime-local" name="acquired_at" required value="${localInputDate()}"></label><label>USB serial / device reference<input name="usb_serial" maxlength="200" placeholder="Optional device identifier"></label></div><label>Acquisition notes<textarea name="description" maxlength="2000" placeholder="Context, collection method, or handling notes"></textarea></label>${formFooter("Register & protect")}</form>`);submitForm(async form=>{const data=new FormData(form);data.set("acquired_at",new Date(data.get("acquired_at")).toISOString());const result=await api("/api/evidence",{method:"POST",body:data});closeModal();await refresh();toast("Evidence registered, encrypted, and signed.");await detailModal(result.evidence_id);});}
function localInputDate(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
async function detailModal(id){const record=await api(`/api/evidence/${encodeURIComponent(id)}`),m=record.manifest,t=fileType(m);openModal("Evidence record",`<div class="detail-top"><span class="file-icon ${t}">${icon(t)}</span><div><h3>${esc(m.filename)}</h3><p>${esc(record.id)}</p><p class="file-size">Size: ${bytes(m.size_bytes)}</p></div>${record.archived?badge("archived","Archived"):badge(record.status)}</div>${record.archived?`<p class="archive-notice">Archived by ${esc(record.archived_by)} on ${date(record.archived_at)}. The original and custody history are retained. Restore this record before transferring it.</p>`:""}<dl class="detail-meta">${[["Case reference",m.case_id],["Registered by",m.handler_name+" ("+m.handler+")"],["Acquisition source",m.source],["Acquisition type",m.source_kind.toUpperCase()],["Acquired at",date(m.acquired_at)],["Last vault check",date(record.last_verified)],["USB / device reference",m.usb_serial||"—"],["Origin node",m.origin_node]].map(([title,value])=>`<div><dt>${title}</dt><dd>${esc(value)}</dd></div>`).join("")}</dl>${m.description?`<p class="form-help">${esc(m.description)}</p>`:""}<div class="hash-label">ORIGINAL SHA-256 FINGERPRINT</div><span class="mono fingerprint">${esc(m.sha256)}</span><div class="detail-actions">${writable()?`<button class="button primary" data-action="verify" data-id="${esc(id)}">${icon("shield")} Verify integrity</button>${!record.archived?`<button class="button secondary" data-action="transfer" data-id="${esc(id)}">${icon("transfer")} Transfer</button>`:""}<button class="button secondary" data-action="${record.archived?"restore":"archive"}" data-id="${esc(id)}">${icon(record.archived?"upload":"folder")} ${record.archived?"Restore evidence":"Remove from active vault"}</button>`:""}<a class="button secondary" href="/api/evidence/${encodeURIComponent(id)}/download">${icon("download")} Original</a><a class="button secondary" href="/api/evidence/${encodeURIComponent(id)}/report">${icon("file")} Signed report</a></div><div class="detail-custody"><h3>Chain of custody ${badge(record.custody_valid?"verified":"alert",record.custody_valid?"Validated":"Invalid")}</h3>${activityList(record.custody,true)}</div>`,true);}
function verifyModal(id){openModal("Verify evidence integrity",`<p class="form-help">Recompute the stored original's hash and check its signed manifest and custody chain. Upload a candidate file to compare an external copy instead.</p><form id="modal-form"><input type="hidden" name="id" value="${esc(id)}">${filePicker({title:"Compare an external copy (optional)",kind:"file",help:`Maximum ${bytes(evidenceLimit())}. Leave empty to verify the encrypted vault original.`})}${formFooter("Run verification")}</form>`);submitForm(async form=>{const data=new FormData();if(form.elements.file.files.length)data.append("file",form.elements.file.files[0]);const result=await api(`/api/evidence/${encodeURIComponent(id)}/verify`,{method:"POST",body:data});await refresh();verificationResult(result);});}
function verificationResult(r){
  const candidate=r.target==="candidate";
  openModal("Verification result",'<div class="check-result '+(r.passed?"":"failed")+'"><h3>'+esc(r.passed?candidate?"External copy matches":"Evidence integrity confirmed":candidate?"External copy comparison failed":"Stored original verification failed")+'</h3><p>'+esc(candidate?"The selected external file was compared with the registered original. Its comparison does not check the vault storage.":"The encrypted vault original was checked against its acquisition manifest.")+'</p></div>'+
    (r.candidate_name?'<p class="form-help">Compared file: '+esc(r.candidate_name)+'</p>':"")+
    analysisMarkup(r.analysis||{summary:r.error||"Verification checks",checks:[{label:"SHA-256 and byte count match",status:r.hash_valid?"passed":"failed"},{label:"Original handler signature",status:r.signature_valid?"passed":"failed"},{label:"Signed custody history",status:r.custody_valid?"passed":"failed"},{label:candidate?"External file readable":"Authenticated vault storage",status:r.storage_valid?"passed":"failed"}]})+
    (candidate&&!r.hash_valid&&r.signature_valid&&r.custody_valid?'<p class="form-help">This is the expected result for a modified copy: the bytes differ. The passing handler signature authenticates the original registration manifest, and the passing custody check validates its history. Neither certifies the modified file.</p>':"")+
    '<div class="hash-label">REGISTERED SHA-256</div><span class="mono fingerprint">'+esc(r.expected_sha256)+'</span><div class="hash-label">COMPUTED SHA-256</div><span class="mono fingerprint">'+esc(r.computed_sha256||"Unavailable")+'</span>'+
    (r.expected_size_bytes!=null?'<p class="settings-note">Registered size: '+bytes(r.expected_size_bytes)+' · Checked size: '+(r.computed_size_bytes==null?"Unavailable":bytes(r.computed_size_bytes))+'</p>':"")+
    '<p class="settings-note">'+date(r.checked_at)+' · Hash '+r.hash_ms.toFixed(3)+' ms · Signature '+r.signature_ms.toFixed(3)+' ms'+(!candidate?' · Vault decryption '+timing(r.decryption_ms):'')+'</p><div class="form-actions"><button class="button secondary" data-action="detail" data-id="'+esc(r.evidence_id)+'">View evidence record</button>'+
    (!r.passed?'<button class="button secondary" data-action="alerts">Security alerts</button>':"")+'<button class="button primary" data-action="close">Done</button></div>');
}
function transferModal(id=""){
  if(!state.data.peers.length){openModal("Connect a receiving node",empty("A trusted peer is required","Download identities from both nodes and add each as a trusted peer. Confirm the key fingerprints before proceeding.",state.user.role==="admin"?"peer":"","Trust a node","transfer"));return;}
  if(!state.data.evidence.length){openModal("Register evidence first",empty("There are no active evidence files","Register a file in the evidence vault before transferring it.",writable()?"register":"","Register evidence"));return;}
  openModal("Transfer evidence",`<p class="form-help">Evidence is checked and encrypted for the selected node. Direct delivery is confirmed only after the receiver returns a valid signed receipt.</p><form id="modal-form"><label>Evidence<select name="evidence_id" required>${state.data.evidence.map(row=>`<option value="${esc(row.id)}" ${row.id===id?"selected":""}>${esc(row.manifest.filename)} - ${esc(row.id)}</option>`).join("")}</select></label><label>Receiving node<select name="peer_id" required>${state.data.peers.map(p=>`<option value="${esc(p.node_id)}">${esc(p.descriptor.name)} - ${esc(p.node_id)}</option>`).join("")}</select></label><fieldset class="delivery-options"><legend>Delivery method</legend><label class="delivery-option"><input type="radio" name="method" value="direct" checked><span><strong>Send directly to peer URL</strong><small>Encrypted network delivery with a signed receiver receipt.</small></span></label><label class="delivery-option"><input type="radio" name="method" value="export"><span><strong>Export encrypted .scpkg package</strong><small>Download a package to import manually on the receiving node.</small></span></label></fieldset><div id="delivery-note" class="delivery-note" aria-live="polite"></div>${formFooter("Send evidence")}</form>`);
  const form=$("#modal-form"),direct=$('input[value="direct"]',form),offline=$('input[value="export"]',form);
  const update=()=>{const peer=state.data.peers.find(p=>p.node_id===form.elements.peer_id.value);direct.disabled=!peer?.url;if(direct.disabled)offline.checked=true;$("#delivery-note").innerHTML=peer?.url?`<strong>Peer URL</strong><p>${esc(peer.url)}</p><small>The receiving node must be running and must trust this node.</small>`:`<p>This peer has no delivery URL. Export a package, or ${state.user.role==="admin"?`<button class="text-link" type="button" data-action="peer-url" data-id="${esc(peer?.node_id||"")}">set its delivery URL</button>`:"ask an administrator to set its delivery URL"}.</p>`;$("button[type=submit]",form).textContent=form.elements.method.value==="direct"?"Send evidence":"Export package";};
  form.elements.peer_id.addEventListener("change",update);form.querySelectorAll('input[name="method"]').forEach(input=>input.addEventListener("change",update));update();
  submitForm(async form=>{const evidence_id=form.elements.evidence_id.value,peer_id=form.elements.peer_id.value;if(!evidence_id)throw new Error("Register evidence before transferring.");if(form.elements.method.value==="direct"){const peer=state.data.peers.find(p=>p.node_id===peer_id);if(!peer?.url)throw new Error("Set this peer's delivery URL before sending directly.");await api(`/api/evidence/${encodeURIComponent(evidence_id)}/transfer`,{method:"POST",body:{peer_id}});toast("Evidence delivered. Signed receiver receipt verified.");}else{const blob=await api(`/api/evidence/${encodeURIComponent(evidence_id)}/export`,{method:"POST",body:{peer_id},blob:true});saveBlob(blob,`${evidence_id}.scpkg`);toast("Encrypted package exported. Delivery is not yet confirmed.");}closeModal();await refresh();});
}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importModal(){openModal("Receive evidence package",`<p class="form-help">Accept an encrypted package addressed to this node. The sender must be a trusted peer. Hash, signatures, custody, and replay checks run before the evidence enters your vault.</p><form id="modal-form">${filePicker({title:"Select a SecureChain package",kind:"download",required:true,accept:".scpkg,application/octet-stream",maximum:packageLimit(),help:`Encrypted .scpkg files from a trusted node · Maximum ${bytes(packageLimit())}`})}${formFooter("Verify & receive")}</form>`);submitForm(async form=>{const result=await api("/api/packages/import",{method:"POST",body:new FormData(form)});closeModal();await refresh();toast("Package authenticated. Evidence accepted into the vault.");await detailModal(result.evidence_id);});}
async function fingerprintPEM(pem){const binary=atob(pem.replace(/-----[^-]+-----/g,"").replace(/\s/g,""));const data=Uint8Array.from(binary,c=>c.charCodeAt(0));const hash=await crypto.subtle.digest("SHA-256",data);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,"0")).join("");}
function peerModal(){
  let descriptor=null;
  openModal("Trust a receiving node",`<p class="form-help">Download the other node's public identity. Compare both key fingerprints through a trusted channel before accepting this identity.</p><form id="modal-form">${filePicker({name:"identity",title:"Select the peer node identity",kind:"file",required:true,accept:".json,application/json",maximum:16384,help:"Public node identity JSON - Maximum 16 KB"})}<div id="peer-preview"></div><label>Delivery URL (optional)<input name="url" type="url" placeholder="https://receiver.example:5001"><small>Leave empty for offline exchange. Local demo receiver: http://127.0.0.1:5001; local demo sender: http://127.0.0.1:5000.</small></label><label>Receiver token (optional)<input name="token" type="password" autocomplete="off" maxlength="256" placeholder="If configured on the receiving node"></label><label><input name="confirmed" type="checkbox" required> I confirmed the signing and encryption fingerprints.</label>${formFooter("Trust this node")}</form>`);
  $("input[name=identity]").addEventListener("change",async event=>{
    const input=event.currentTarget,file=input.files[0],form=input.form;
    descriptor=null;form.elements.confirmed.checked=false;$("#peer-preview").innerHTML="";$("#modal-error").textContent="";
    if(!file)return;
    try{const sizeError=fileSizeError(input);if(sizeError)throw new Error(sizeError);const value=JSON.parse(await file.text());const signing=await fingerprintPEM(value.signing_key),encryption=await fingerprintPEM(value.encryption_key);if(input!==$("input[name=identity]")||input.files[0]!==file)return;descriptor=value;$("#peer-preview").innerHTML=`<div class="detail-meta"><div><dt>Node</dt><dd>${esc(value.name)}</dd></div><div><dt>Node ID</dt><dd>${esc(value.node_id)}</dd></div></div><div class="hash-label">SIGNING KEY FINGERPRINT</div><span class="mono fingerprint">${signing}</span><div class="hash-label">ENCRYPTION KEY FINGERPRINT</div><span class="mono fingerprint">${encryption}</span><p class="settings-note">Identity signature is validated on acceptance.</p>`;}catch(error){if(input!==$("input[name=identity]")||input.files[0]!==file)return;$("#peer-preview").innerHTML="";$("#modal-error").textContent="Could not read the identity file: "+error.message;}
  });
  submitForm(async form=>{if(!descriptor)throw new Error("Select a valid node identity file.");await api("/api/peers",{method:"POST",body:{descriptor,url:form.elements.url.value,token:form.elements.token.value}});closeModal();await refresh();toast("Peer identity validated and pinned.");});
}
function peerUrlModal(id){
  const peer=state.data.peers.find(p=>p.node_id===id);if(!peer)throw new Error("Trusted node not found.");
  openModal("Edit peer delivery URL",`<p class="form-help">Configure direct delivery to ${esc(peer.descriptor.name)}. This updates connection settings while retaining its trusted identity and key fingerprints.</p><form id="modal-form"><label>Delivery URL<input name="url" type="url" maxlength="2048" value="${esc(peer.url||"")}" placeholder="https://receiver.example:5001"><small>Use the peer's base URL. HTTPS is required except explicitly enabled local demo HTTP. Leave empty for offline exchange.</small></label><label><input name="replace_token" type="checkbox"> Replace or clear the saved receiver token</label><label>New receiver token<input name="token" type="password" autocomplete="new-password" maxlength="256"><small>The existing token is retained unless replacement is selected. A blank replacement clears it.</small></label>${formFooter("Save connection")}</form>`);
  submitForm(async form=>{const body={url:form.elements.url.value};if(form.elements.replace_token.checked)body.token=form.elements.token.value;await api(`/api/peers/${encodeURIComponent(id)}`,{method:"PUT",body});closeModal();await refresh();toast("Peer delivery settings updated.");});
}
function userModal(){openModal("Add an authorized handler",`<p class="form-help">Each handler receives an individual RSA signing key. Investigators can acquire, verify, and transfer evidence; viewers can inspect and export records.</p><form id="modal-form"><div class="form-grid"><label>Full name<input name="name" required maxlength="120"></label><label>Username<input name="username" required maxlength="64"></label></div><label>Initial password<input name="password" type="password" minlength="12" maxlength="256" required autocomplete="new-password" data-new-password="true"><small>Include uppercase and lowercase letters, a number, and a special character. Share it securely with the handler.</small></label><label>Access role<select name="role"><option value="investigator">Investigator</option><option value="viewer">Viewer</option><option value="admin">Administrator</option></select></label>${formFooter("Create handler")}</form>`);submitForm(async form=>{await api("/api/users",{method:"POST",body:Object.fromEntries(new FormData(form))});closeModal();await refresh();toast("Handler account and signing identity created.");});}
function alertsModal(){const alerts=state.data.alerts;openModal("Security alerts",alerts.length?alerts.map(a=>`<div class="alert-item ${a.acknowledged?"acknowledged":""}">${icon("alert")}<div><strong>${esc(a.message)}</strong><p>${esc(a.evidence_id||"Node transfer")} · ${date(a.created_at)}${a.acknowledged?" · Acknowledged":""}</p></div>${!a.acknowledged&&writable()?`<button class="button secondary small-button" data-action="acknowledge" data-id="${a.id}">Acknowledge</button>`:""}</div>`).join(""):empty("No open concerns","Failed verification and rejected transfer alerts are recorded here.","","","shield"),true);}

function analysisMarkup(analysis){
  if(!analysis)return "";
  const labels={passed:"Passed",failed:"Failed",not_checked:"Not checked"};
  return '<section class="verification-analysis"><h3>Verification analysis</h3>'+
    '<p>'+esc(analysis.summary||analysis.reason||"Check results")+'</p>'+
    (analysis.reason&&analysis.reason!==analysis.summary?'<p class="analysis-reason">'+esc(analysis.reason)+'</p>':"")+
    (analysis.checks||[]).map(check=>'<div class="analysis-check '+esc(check.status)+'"><div><strong>'+esc(check.label)+'</strong><span class="check-status">'+esc(labels[check.status]||"Not checked")+'</span></div><p>'+esc(check.detail)+'</p>'+
    (check.expected_sha256?'<div class="hash-label">REGISTERED SHA-256</div><span class="mono fingerprint">'+esc(check.expected_sha256)+'</span><div class="hash-label">COMPUTED SHA-256</div><span class="mono fingerprint">'+esc(check.computed_sha256||"Unavailable")+'</span>':"")+'</div>').join("")+
    '</section>';
}
function eventInfo(payload){
  const d=payload.detail||{}, base=actions[payload.action]||[payload.action,"clock"];
  let title=base[0], explanation="";
  const peerName=id=>{const peer=(state.data.peers||[]).find(p=>p.node_id===id);return peer?peer.descriptor.name+" ("+id+")":id||"Unknown node";};
  const checks=[["hash_valid","SHA-256 and byte count"],["signature_valid","original handler signature"],["custody_valid","signed custody history"],["storage_valid",d.target==="candidate"?"candidate file read":"encrypted vault authentication"]];
  switch(payload.action){
    case "registered": title="Original file registered and encrypted"; explanation="Source: "+(d.source||"not recorded")+" · Acquisition: "+(d.source_kind||"file")+" · Original SHA-256: "+(d.sha256||"not recorded");break;
    case "verified": case "verification_failed":
      title=d.target==="candidate"?(d.passed?"External copy matches the registered original":d.hash_valid===false?"External copy differs from the registered original":"External copy comparison failed"):(d.passed?"Stored original passed integrity verification":"Stored original failed integrity verification");
      explanation=(d.candidate_name?"Compared file: "+d.candidate_name+". ":"")+checks.filter(([key])=>typeof d[key]==="boolean").map(([key,label])=>label+": "+(d[key]?"passed":"failed")).join(" · ")+(d.error?". "+d.error:"");
      break;
    case "transfer_prepared": explanation="Encrypted package prepared for "+peerName(d.recipient)+". Package: "+(d.package_id||"not recorded");break;
    case "transferred": title="Direct delivery confirmed by signed receiver receipt";explanation="Receiver: "+peerName(d.receiver||d.recipient)+". Package: "+(d.package_id||"not recorded");break;
    case "received": title="Package authenticated and original accepted";explanation="Sender: "+peerName(d.sender)+". Package: "+(d.package_id||"not recorded")+". Hash, signatures and custody validated.";break;
    case "transfer_rejected": explanation=d.reason||"Package rejected before registration.";if(d.stage)explanation+=" Failed check: "+((d.checks||[]).find(check=>check.key===d.stage)?.label||d.stage)+".";break;
    case "transfer_failed": explanation=d.reason||d.error||"No valid signed receiver receipt was obtained; delivery remains unconfirmed.";break;
    case "evidence_archived": title="Evidence removed from the active vault";explanation="Encrypted original and signed custody history retained. The record can be restored.";break;
    case "evidence_restored": title="Evidence restored to the active vault";explanation="The same encrypted original and registration manifest remain preserved.";break;
    case "downloaded": explanation="Verified original downloaded"+(d.size_bytes!=null?" · Size: "+bytes(d.size_bytes):"");break;
    case "peer_updated": title="Trusted node delivery connection updated";explanation="Node: "+peerName(d.node_id)+" · URL: "+(d.url||"offline exchange");break;
    default: explanation=d.reason||"";
  }
  return {title,kind:base[1],explanation};
}
function archiveModal(id){
  const record=[...state.data.evidence,...(state.data.archived_evidence||[])].find(row=>row.id===id);
  openModal("Remove evidence from active vault",'<p class="form-help">Archive '+esc(record?.manifest.filename||id)+' to remove it from the active list. Its encrypted original, registration and signed custody history remain available under Archived evidence. You can restore it there.</p><form id="modal-form">'+formFooter("Archive evidence")+'</form>');
  submitForm(async()=>{await api('/api/evidence/'+encodeURIComponent(id)+'/archive',{method:"POST"});closeModal();await refresh();toast("Evidence archived. Its original and custody history are retained.");});
}
async function restoreEvidence(id){
  await api('/api/evidence/'+encodeURIComponent(id)+'/restore',{method:"POST"});
  await refresh();toast("Evidence restored to the active vault.");await detailModal(id);
}
let updatePending=false;
async function pollUpdates(){
  if(!state.user||document.hidden||updatePending||state.busy)return;
  updatePending=true;
  try{await refresh({background:true});}catch{}finally{updatePending=false;}
}
setInterval(pollUpdates,10000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)pollUpdates();});

document.addEventListener("click",async event=>{const el=event.target.closest("[data-action]");if(!el)return;const {action,id}=el.dataset;try{if(["register","verify","transfer","choose-transfer","import","acknowledge","archive","restore"].includes(action)&&!writable())throw new Error("Your role does not allow this action.");if(["peer","peer-url","user"].includes(action)&&state.user?.role!=="admin")throw new Error("An administrator is required for this action.");switch(action){case"register":registerModal();break;case"detail":await detailModal(id);break;case"verify":verifyModal(id);break;case"transfer":transferModal(id);break;case"choose-transfer":transferModal();break;case"import":importModal();break;case"peer":peerModal();break;case"peer-url":peerUrlModal(id);break;case"archive":archiveModal(id);break;case"restore":await restoreEvidence(id);break;case"active-vault":state.archived=false;render();break;case"archived-vault":state.archived=true;render();break;case"user":userModal();break;case"alerts":await refresh({background:true});alertsModal();break;case"acknowledge":await api(`/api/alerts/${id}/acknowledge`,{method:"POST"});await refresh();alertsModal();break;case"close":closeModal();break;}}catch(error){toast(error.message,true);}});
$("#close-modal").addEventListener("click",closeModal);
$("#modal").addEventListener("click",event=>{if(event.target===$("#modal")){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
$("#logout").addEventListener("click",async()=>{try{await api("/api/logout",{method:"POST"});state.user=null;const info=await api("/api/session");state.csrf=info.csrf;closeModal();showAuth();}catch(error){toast(error.message,true);}});
$("#auth-form").addEventListener("submit", async event => {
  event.preventDefault();
  // currentTarget is cleared after event dispatch; retain the form across await.
  const form = event.currentTarget;
  const button = $("button[type=submit]", form);
  button.disabled = true;
  $("#auth-error").textContent = "";
  try {
    const result = await api(state.setup ? "/api/setup" : "/api/login", {
      method: "POST",
      body: Object.fromEntries(new FormData(form))
    });
    state.user = result.user;
    state.csrf = result.csrf;
    state.setup = false;
    form.reset();
    await showWorkspace();
  } catch (error) {
    $("#auth-error").textContent = error.message;
  } finally {
    button.disabled = false;
  }
});
window.addEventListener("hashchange",()=>{state.page=pages[location.hash.slice(1)]?location.hash.slice(1):"overview";state.query="";state.filter="all";state.archived=false;if(state.user){render();pollUpdates();}});
(async()=>{try{const info=await api("/api/session");state.user=info.user;state.csrf=info.csrf;state.setup=info.setup_required;$("#auth-node").textContent=info.node_name;$("#sidebar-node").textContent=info.node_name;state.page=pages[location.hash.slice(1)]?location.hash.slice(1):"overview";if(state.user)await showWorkspace();else showAuth();}catch(error){$("#loading p").textContent="Unable to connect: "+error.message;}})();
